//! Runtime for inflection crates generated by `flexion-train`.
//!
//! A generated crate (`english`, `russian`, …) is a thin typed API over one
//! [`Model`]: a static blob holding, per part of speech, the **edits** that
//! turn a lemma into its forms, the **inflection classes** (one edit per cell,
//! plus inherent features such as gender), and a **suffix tree** over lemmas
//! read from their last letter backwards. Each tree node stores a probability
//! distribution over classes; walking a word to its deepest matching node
//! gives the classes that word most likely belongs to. Attested exceptions are
//! simply deep nodes, so memorized words and general patterns are one
//! structure.
//!
//! Every function here is total and never panics. A corrupt blob yields no
//! model ([`Model::from_bytes`] returns `None`), and generated crates fall
//! back to returning the input unchanged.

#![deny(clippy::arithmetic_side_effects)]

pub mod format;
mod pos;
pub mod text;
pub mod write;

use format::{Bytes, DIST_LEN, EDIT_LEN, HEADER_LEN, NODE_LEN, NONE, POS_HEADER_LEN, class_len};
pub use pos::{Citation, Edit, Pos};
pub use text::{Casing, Spelling, SpellingStrings, VowelSet, Word};

/// One possible form, with the model's confidence in it.
#[derive(Debug, Clone, PartialEq)]
pub struct Candidate {
    pub form: String,
    /// Probability in `0.0..=1.0`. Candidates of one call sum to 1.
    pub confidence: f32,
}

/// Output options shared by every query.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Options {
    /// Write stress marks (Russian stress, Greek accents).
    pub stress: bool,
    /// Write the letters the spelling can write plain with their marks
    /// (Latin macrons, Greek length marks). Off writes them plain.
    pub marks: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            stress: true,
            marks: true,
        }
    }
}

/// A loaded model: a validated view over a static blob.
#[derive(Debug, Clone)]
pub struct Model<'a> {
    pub(crate) strings: &'a str,
    pub(crate) spelling: Spelling<'a>,
    parts: Vec<PosHeader<'a>>,
}

#[derive(Debug, Clone)]
pub(crate) struct PosHeader<'a> {
    pub(crate) cells: usize,
    pub(crate) inherent: usize,
    pub(crate) edits: usize,
    pub(crate) n_edits: usize,
    pub(crate) classes: usize,
    pub(crate) n_classes: usize,
    pub(crate) class_len: usize,
    pub(crate) nodes: usize,
    pub(crate) n_nodes: usize,
    pub(crate) dist: usize,
    pub(crate) n_dist: usize,
    pub(crate) lemma_cell: Option<usize>,
    pub(crate) walk: Walk,
    pub(crate) chars: usize,
    /// The part of speech whose model restores this one's lemmas.
    pub(crate) restore: Option<usize>,
    /// Every word is written with a capital.
    pub(crate) capitalized: bool,
    /// The language's main letter block (`char >> 8`), for child tables.
    pub(crate) block: u32,
    /// Every node, decoded once at load so a walk reads plain fields.
    pub(crate) tree: Vec<NodeRec>,
    /// The other tables, decoded once at load.
    pub(crate) edit_list: Vec<pos::Edit<'a>>,
    /// One edit index per class and cell (stride `cells`).
    /// Classes as stored: per class one sub-vector index per cell group
    /// (stride `n_groups`); per group, where its sub-vectors start in
    /// `sub_edits` and how many cells each has; per cell, its group and its
    /// place in it. Classes share sub-vectors, so this stays small.
    pub(crate) class_subs: Vec<u32>,
    pub(crate) n_groups: usize,
    pub(crate) group_tables: Vec<(usize, usize)>,
    pub(crate) sub_edits: Vec<u32>,
    pub(crate) cell_group: Vec<(u32, u32)>,
    /// Each class's longest stripped suffix and start, folded for lookup: a
    /// class fits a word whose key ends and starts with them.
    /// Per class: the `(start, end)` of its folded stripped suffix and of its
    /// folded stripped start in `class_text`.
    pub(crate) class_folds: Vec<[(u32, u32); 2]>,
    pub(crate) class_text: String,
    /// Per class: the stress rule and mark of its lemma cell (the lemma's own
    /// stress), when it has one.
    pub(crate) class_lemma: Vec<(format::Stress, u8)>,
    /// One value per class and inherent feature (stride `inherent`).
    pub(crate) class_values: Vec<u8>,
    pub(crate) entries: Vec<(u32, f32)>,
    /// Running sums of the entries' probabilities (one more than `entries`).
    pub(crate) entry_cum: Vec<f64>,
    /// Per node: 1 + its index in `tables` if it has one, else 0.
    pub(crate) table_of: Vec<u32>,
    /// Direct child indexes for nodes with many children, built at load.
    pub(crate) tables: Vec<ChildTable>,
    /// Join classes: one edit index per cell (stride `cells`).
    pub(crate) join_classes: Vec<u32>,
    /// The join model's prefixes, sorted.
    pub(crate) joins: Vec<JoinRec<'a>>,
    pub(crate) join_entries: Vec<(u32, f32)>,
    /// `(feature, attested value, joined value, probability)` (see
    /// [`write::JoinSpec::inherent`]).
    pub(crate) join_inherent: Vec<(u8, u8, u8, f32)>,
    /// Part models: `(the principal part's cell, the model's part of speech)`.
    pub(crate) part_models: Vec<(usize, usize)>,
    /// Per cell: 0, or `k + 1` to build it from part model `k`.
    pub(crate) sources: Vec<u8>,
    /// Lemmas written in full that another part of speech attests: `(the
    /// hash of the key, written)`.
    pub(crate) lexicon: Vec<(u32, &'a str)>,
    /// An open-addressing hash index over `lexicon`, built at load (a
    /// sorted search would touch a dozen far-apart strings per call): per
    /// slot 1 + the entry's index, 0 for empty; a power of two long.
    pub(crate) lexicon_index: Vec<u32>,
}

/// FNV-1a, for the lexicon's index.
pub(crate) fn hash(key: &str) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in key.bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    h
}

impl PosHeader<'_> {
    /// Class `class`'s edit index for `cell` ([`NONE`] when it has no form
    /// there).
    pub(crate) fn class_edit(&self, class: usize, cell: usize) -> Option<u32> {
        let &(g, off) = self.cell_group.get(cell)?;
        let g = usize::try_from(g).ok()?;
        let sub = *self
            .class_subs
            .get(class.checked_mul(self.n_groups)?.checked_add(g)?)?;
        let &(start, len) = self.group_tables.get(g)?;
        let at = start
            .checked_add(usize::try_from(sub).ok()?.checked_mul(len)?)?
            .checked_add(usize::try_from(off).ok()?)?;
        self.sub_edits.get(at).copied()
    }
}

/// One prefix of the join model.
#[derive(Debug, Clone, Copy)]
pub(crate) struct JoinRec<'a> {
    /// Folded, as lookup keys are.
    pub(crate) prefix: &'a str,
    /// How likely an unseen word with this prefix and an attested rest joins.
    pub(crate) split: f32,
    pub(crate) first: usize,
    pub(crate) count: usize,
    pub(crate) first_inherent: usize,
    pub(crate) count_inherent: usize,
}

/// One tree node, decoded.
#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct NodeRec {
    pub(crate) first_child: u32,
    pub(crate) dist: u32,
    pub(crate) children: u16,
    pub(crate) dist_len: u16,
    /// The label's first character.
    pub(crate) first: u32,
    /// The label's length in bytes.
    pub(crate) label_len: u16,
    /// The label's offset in the string area.
    pub(crate) label: u32,
}

/// Nodes with more children than this get a direct [`ChildTable`].
const TABLE_MIN_CHILDREN: usize = 8;

/// A direct index of one node's children by symbol, for symbols below 256 or
/// in the language's main letter block: offset from the first child + 1, 0
/// for none. A walk's widest nodes (the root, the first letters) get one, so
/// they cost one lookup instead of a search.
#[derive(Debug, Clone)]
pub(crate) struct ChildTable {
    pub(crate) low: [u16; 256],
    pub(crate) high: [u16; 256],
}

impl ChildTable {
    /// `Some(None)`: the symbol is covered and the node has no such child.
    /// `None`: the symbol is outside the table.
    pub(crate) fn get(&self, block: u32, c: char) -> Option<Option<usize>> {
        let u = u32::from(c);
        let v = if u < 256 {
            *self.low.get(usize::try_from(u).ok()?)?
        } else if u >> 8 == block {
            *self.high.get(usize::try_from(u & 255).ok()?)?
        } else {
            return None;
        };
        Some(usize::from(v).checked_sub(1))
    }
}

/// How a key is turned into the sequence of symbols the tree is walked with.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Walk {
    /// Insert a syllable-count token after this many letters (from the end).
    pub syllable_depth: Option<usize>,
    /// Syllable counts above this share the last bucket.
    pub syllable_max: usize,
    /// Insert the word's first letter as a token after this many letters
    /// (from the end), for classes that change the start of the word.
    pub initial_depth: Option<usize>,
}

impl Walk {
    pub fn encode(self) -> u32 {
        let depth = |d: Option<usize>| {
            d.map_or(0, |d| {
                u32::try_from(d).unwrap_or(254).min(254).saturating_add(1)
            })
        };
        depth(self.syllable_depth)
            | (u32::try_from(self.syllable_max).unwrap_or(255).min(255) << 8)
            | (depth(self.initial_depth) << 16)
    }

    pub fn decode(v: u32) -> Walk {
        let depth = |d: u32| (d != 0).then(|| usize::try_from(d.saturating_sub(1)).unwrap_or(0));
        Walk {
            syllable_depth: depth(v & 0xff),
            syllable_max: usize::try_from((v >> 8) & 0xff).unwrap_or(0),
            initial_depth: depth((v >> 16) & 0xff),
        }
    }

    /// The token for a key's syllable count.
    pub fn syllable_token(self, groups: usize) -> char {
        u32::try_from(groups.min(self.syllable_max))
            .ok()
            .and_then(|b| char::from_u32(format::SYLLABLE_TOKEN.saturating_add(b)))
            .unwrap_or(format::BOUNDARY)
    }

    /// The token for a key's first letter.
    pub fn initial_token(key: &str) -> char {
        key.chars()
            .next()
            .and_then(|c| char::from_u32(format::INITIAL_TOKEN.saturating_add(u32::from(c))))
            .unwrap_or(format::BOUNDARY)
    }

    /// The walk for `key`: its letters from the last one back, the syllable
    /// and first-letter tokens where configured, then the start-of-word
    /// symbol.
    pub fn symbols(self, sp: &Spelling<'_>, key: &str) -> Vec<char> {
        let letters: Vec<char> = key.chars().rev().collect();
        let mut tokens: Vec<(usize, char)> = Vec::new();
        if let Some(d) = self.syllable_depth {
            tokens.push((
                d.min(letters.len()),
                self.syllable_token(sp.vowel_groups(key)),
            ));
        }
        if let Some(d) = self.initial_depth {
            tokens.push((d.min(letters.len()), Walk::initial_token(key)));
        }
        // At equal depths the syllable token comes first.
        tokens.sort_by_key(|t| t.0);
        let mut out = Vec::with_capacity(letters.len().saturating_add(3));
        let mut next = tokens.iter().peekable();
        for (i, &c) in letters.iter().enumerate() {
            while let Some(&&(d, t)) = next.peek() {
                if d != i {
                    break;
                }
                out.push(t);
                next.next();
            }
            out.push(c);
        }
        out.extend(next.map(|&(_, t)| t));
        out.push(format::BOUNDARY);
        out
    }
}

impl<'a> Model<'a> {
    /// Validate and load a blob written by `flexion-train`.
    pub fn from_bytes(bytes: &'a [u8]) -> Option<Model<'a>> {
        let b = Bytes(bytes);
        if bytes.get(0..4)? != format::MAGIC || b.u32(4)? != format::VERSION {
            return None;
        }
        let s_off = b.usize(8)?;
        let s_len = b.usize(12)?;
        let strings = std::str::from_utf8(bytes.get(s_off..s_off.checked_add(s_len)?)?).ok()?;
        let n_pos = b.usize(16)?;
        let flags = b.u32(20)?;
        let spelling = Spelling::new(
            flags & format::FLAG_FOLD_CASE != 0,
            flags & format::FLAG_MARK_MONOSYLLABLES != 0,
            text::SpellingStrings {
                stress_marks: b.str(strings, 24)?,
                vowels: b.str(strings, 32)?,
                implicit: b.str(strings, 40)?,
                fold_from: b.str(strings, 48)?,
                fold_to: b.str(strings, 56)?,
                strip_marks: b.str(strings, 64)?,
                unmark_from: b.str(strings, 72)?,
                unmark_to: b.str(strings, 80)?,
                stress_table: b.str(strings, 88)?,
                syllabic: b.str(strings, 96)?,
                mute: b.str(strings, 104)?,
                diphthongs: b.str(strings, 112)?,
                hiatus: b.str(strings, 120)?,
            },
        );
        let mut parts = Vec::with_capacity(n_pos);
        for i in 0..n_pos {
            let at = HEADER_LEN.checked_add(i.checked_mul(POS_HEADER_LEN)?)?;
            let field = |n: usize| b.usize(at.checked_add(n.checked_mul(4)?)?);
            let cells = field(0)?;
            let inherent = field(1)?;
            let lemma = b.u32(at.checked_add(40)?)?;
            let h = PosHeader {
                cells,
                inherent,
                edits: field(2)?,
                n_edits: field(3)?,
                classes: field(4)?,
                n_classes: field(5)?,
                class_len: 0,
                nodes: field(6)?,
                n_nodes: field(7)?,
                dist: field(8)?,
                n_dist: field(9)?,
                lemma_cell: (lemma != NONE)
                    .then(|| usize::try_from(lemma).ok())
                    .flatten(),
                walk: Walk::decode(b.u32(at.checked_add(44)?)?),
                chars: b.usize(at.checked_add(48)?)?,
                restore: {
                    let r = b.u32(at.checked_add(56)?)?;
                    (r != NONE).then(|| usize::try_from(r).ok()).flatten()
                },
                capitalized: b.u32(at.checked_add(60)?)? & format::POS_CAPITALIZED != 0,
                block: spelling.vowel_set.block(),
                tree: Vec::new(),
                edit_list: Vec::new(),
                class_subs: Vec::new(),
                n_groups: 0,
                group_tables: Vec::new(),
                sub_edits: Vec::new(),
                cell_group: Vec::new(),
                class_folds: Vec::new(),
                class_text: String::new(),
                class_lemma: Vec::new(),
                class_values: Vec::new(),
                entries: Vec::new(),
                entry_cum: Vec::new(),
                table_of: Vec::new(),
                tables: Vec::new(),
                join_classes: Vec::new(),
                joins: Vec::new(),
                join_entries: Vec::new(),
                join_inherent: Vec::new(),
                part_models: Vec::new(),
                sources: Vec::new(),
                lexicon: Vec::new(),
                lexicon_index: Vec::new(),
            };
            let dist_len = if b.u32(at.checked_add(60)?)? & format::POS_WIDE_DIST != 0 {
                DIST_LEN
            } else {
                format::NARROW_DIST_LEN
            };
            // Every table must lie inside the blob.
            let ends = [
                h.edits.checked_add(h.n_edits.checked_mul(EDIT_LEN)?)?,
                h.nodes.checked_add(h.n_nodes.checked_mul(NODE_LEN)?)?,
                h.dist.checked_add(h.n_dist.checked_mul(dist_len)?)?,
                h.chars.checked_add(h.n_nodes.checked_mul(4)?)?,
            ];
            if ends.iter().any(|&e| e > bytes.len()) || h.n_nodes == 0 {
                return None;
            }
            let mut h = h;
            h.table_of = vec![0; h.n_nodes];
            h.tree = Vec::with_capacity(h.n_nodes);
            for node in 0..h.n_nodes {
                let at = h.nodes.checked_add(node.checked_mul(NODE_LEN)?)?;
                let u16_at = |n: usize| -> Option<u16> {
                    Some(u16::from_le_bytes(
                        bytes
                            .get(at.checked_add(n)?..at.checked_add(n.checked_add(2)?)?)?
                            .try_into()
                            .ok()?,
                    ))
                };
                let packed = b.u32(h.chars.checked_add(node.checked_mul(4)?)?)?;
                h.tree.push(NodeRec {
                    label: b.u32(at)?,
                    first_child: b.u32(at.checked_add(4)?)?,
                    dist: b.u32(at.checked_add(8)?)?,
                    children: u16_at(12)?,
                    dist_len: u16_at(14)?,
                    first: packed & ((1 << format::CHAR_BITS) - 1),
                    label_len: u16::try_from(packed >> format::CHAR_BITS).ok()?,
                });
                let first = b.usize(at.checked_add(4)?)?;
                let count = usize::from(u16_at(12)?);
                if count <= TABLE_MIN_CHILDREN {
                    continue;
                }
                let mut t = ChildTable {
                    low: [0; 256],
                    high: [0; 256],
                };
                for i in 0..count {
                    let idx = first.checked_add(i)?;
                    let v = b.u32(h.chars.checked_add(idx.checked_mul(4)?)?)?;
                    let c = v & ((1 << format::CHAR_BITS) - 1);
                    let slot = if c < 256 {
                        t.low.get_mut(usize::try_from(c).ok()?)
                    } else if c >> 8 == h.block {
                        t.high.get_mut(usize::try_from(c & 255).ok()?)
                    } else {
                        None
                    };
                    if let Some(slot) = slot {
                        *slot = u16::try_from(i).ok()?.checked_add(1)?;
                    }
                }
                h.tables.push(t);
                if let Some(slot) = h.table_of.get_mut(node) {
                    *slot = u32::try_from(h.tables.len()).ok()?;
                }
            }
            // Edits, classes and distribution entries.
            for i in 0..h.n_edits {
                let at = h.edits.checked_add(i.checked_mul(EDIT_LEN)?)?;
                let byte = |n: usize| b.u8(at.checked_add(n)?);
                // A string: its offset at `n`, its length in byte `25 + n / 4`.
                let text = |n: usize| -> Option<&str> {
                    let off = b.usize(at.checked_add(n)?)?;
                    let len = usize::from(byte(25usize.checked_add(n / 4)?)?);
                    strings.get(off..off.checked_add(len)?)
                };
                h.edit_list.push(pos::Edit {
                    prefix: text(0)?,
                    strip: text(4)?,
                    add: text(8)?,
                    front: text(12)?,
                    stress: format::Stress::decode(byte(16)?, byte(17)?),
                    strip_chars: byte(18)?,
                    vowels: [byte(19)?, byte(20)?, byte(21)?],
                    front_chars: byte(22)?,
                    front_vowels: byte(23)?,
                    mark: byte(24)?,
                });
            }
            // Groups: their sizes, then each group's shared sub-vectors.
            let mut cursor = b.usize(at.checked_add(52)?)?;
            let n_groups = b.usize(cursor)?;
            cursor = cursor.checked_add(4)?;
            let mut sizes = Vec::with_capacity(n_groups);
            for _ in 0..n_groups {
                sizes.push(b.usize(cursor)?);
                cursor = cursor.checked_add(4)?;
            }
            if sizes.iter().try_fold(0usize, |a, &x| a.checked_add(x))? != h.cells {
                return None;
            }
            let mut counts = Vec::with_capacity(n_groups);
            for (g, &len) in sizes.iter().enumerate() {
                let n = b.usize(cursor)?;
                cursor = cursor.checked_add(4)?;
                if cursor.checked_add(n.checked_mul(len)?.checked_mul(4)?)? > bytes.len() {
                    return None;
                }
                h.group_tables.push((h.sub_edits.len(), len));
                for _ in 0..n.checked_mul(len)? {
                    h.sub_edits.push(b.u32(cursor)?);
                    cursor = cursor.checked_add(4)?;
                }
                counts.push(n);
                for off in 0..len {
                    h.cell_group
                        .push((u32::try_from(g).ok()?, u32::try_from(off).ok()?));
                }
            }
            h.n_groups = n_groups;
            h.class_len = class_len(n_groups, h.inherent);
            if h.classes
                .checked_add(h.n_classes.checked_mul(h.class_len)?)?
                > bytes.len()
            {
                return None;
            }
            for c in 0..h.n_classes {
                let at = h.classes.checked_add(c.checked_mul(h.class_len)?)?;
                for (g, &n) in counts.iter().enumerate() {
                    let id = b.u32(at.checked_add(g.checked_mul(4)?)?)?;
                    if usize::try_from(id).ok()? >= n {
                        return None;
                    }
                    h.class_subs.push(id);
                }
                let strip_at = at.checked_add(n_groups.checked_mul(4)?)?;
                let strip = b.str(strings, strip_at)?;
                let mut span = |s: &str| {
                    let start = u32::try_from(h.class_text.len()).unwrap_or(u32::MAX);
                    h.class_text.push_str(&spelling.fold_str(s));
                    (start, u32::try_from(h.class_text.len()).unwrap_or(u32::MAX))
                };
                let strip_span = span(strip);
                let front = b.str(strings, strip_at.checked_add(8)?)?;
                let front_span = span(front);
                h.class_folds.push([strip_span, front_span]);
                let lemma_rule = h
                    .lemma_cell
                    .and_then(|cell| h.class_edit(c, cell))
                    .and_then(|id| h.edit_list.get(usize::try_from(id).ok()?))
                    .map_or((format::Stress::Unmarked, 0), |e| (e.stress, e.mark));
                h.class_lemma.push(lemma_rule);
                for f in 0..h.inherent {
                    h.class_values
                        .push(b.u8(strip_at.checked_add(16)?.checked_add(f)?)?);
                }
            }
            for i in 0..h.n_dist {
                let at = h.dist.checked_add(i.checked_mul(dist_len)?)?;
                h.entries.push(if dist_len == DIST_LEN {
                    (b.u32(at)?, b.f32(at.checked_add(4)?)?)
                } else {
                    let word = b.u32(at)?;
                    let q = f32::from(u16::try_from(word >> 16).ok()?);
                    (word & 0xffff, q / f32::from(u16::MAX))
                });
            }
            h.entry_cum = std::iter::once(0f64)
                .chain(h.entries.iter().scan(0f64, |acc, &(_, p)| {
                    *acc += f64::from(p);
                    Some(*acc)
                }))
                .collect();
            // The join model.
            let mut cursor = b.usize(at.checked_add(64)?)?;
            let n_classes = b.usize(cursor)?;
            cursor = cursor.checked_add(4)?;
            let class_bytes = n_classes.checked_mul(h.cells)?.checked_mul(4)?;
            if cursor.checked_add(class_bytes)? > bytes.len() {
                return None;
            }
            for _ in 0..n_classes.checked_mul(h.cells)? {
                h.join_classes.push(b.u32(cursor)?);
                cursor = cursor.checked_add(4)?;
            }
            let n_joins = b.usize(cursor)?;
            cursor = cursor.checked_add(4)?;
            if cursor.checked_add(n_joins.checked_mul(28)?)? > bytes.len() {
                return None;
            }
            let (mut n_entries, mut n_inherent) = (0usize, 0usize);
            for _ in 0..n_joins {
                let j = JoinRec {
                    prefix: b.str(strings, cursor)?,
                    split: b.f32(cursor.checked_add(8)?)?,
                    first: b.usize(cursor.checked_add(12)?)?,
                    count: b.usize(cursor.checked_add(16)?)?,
                    first_inherent: b.usize(cursor.checked_add(20)?)?,
                    count_inherent: b.usize(cursor.checked_add(24)?)?,
                };
                n_entries = n_entries.max(j.first.checked_add(j.count)?);
                n_inherent = n_inherent.max(j.first_inherent.checked_add(j.count_inherent)?);
                h.joins.push(j);
                cursor = cursor.checked_add(28)?;
            }
            if cursor.checked_add(n_entries.saturating_add(n_inherent).checked_mul(DIST_LEN)?)?
                > bytes.len()
            {
                return None;
            }
            for _ in 0..n_entries {
                h.join_entries
                    .push((b.u32(cursor)?, b.f32(cursor.checked_add(4)?)?));
                cursor = cursor.checked_add(DIST_LEN)?;
            }
            for _ in 0..n_inherent {
                h.join_inherent.push((
                    b.u8(cursor)?,
                    b.u8(cursor.checked_add(1)?)?,
                    b.u8(cursor.checked_add(2)?)?,
                    b.f32(cursor.checked_add(4)?)?,
                ));
                cursor = cursor.checked_add(DIST_LEN)?;
            }
            // Part models.
            let mut cursor = b.usize(at.checked_add(68)?)?;
            let n_models = b.usize(cursor)?;
            cursor = cursor.checked_add(4)?;
            if n_models > n_pos {
                return None;
            }
            for _ in 0..n_models {
                let cell = b.usize(cursor)?;
                let model = b.usize(cursor.checked_add(4)?)?;
                if model >= n_pos || model == i {
                    return None;
                }
                h.part_models.push((cell, model));
                cursor = cursor.checked_add(8)?;
            }
            h.sources = bytes.get(cursor..cursor.checked_add(h.cells)?)?.to_vec();
            // The lexicon.
            let mut cursor = b.usize(at.checked_add(72)?)?;
            let n_lexicon = b.usize(cursor)?;
            cursor = cursor.checked_add(4)?;
            if cursor.checked_add(n_lexicon.checked_mul(12)?)? > bytes.len() {
                return None;
            }
            h.lexicon = Vec::with_capacity(n_lexicon);
            for _ in 0..n_lexicon {
                h.lexicon
                    .push((b.u32(cursor.checked_add(8)?)?, b.str(strings, cursor)?));
                cursor = cursor.checked_add(12)?;
            }
            if !h.lexicon.is_empty() {
                let slots = h.lexicon.len().checked_mul(2)?.next_power_of_two();
                h.lexicon_index = vec![0; slots];
                let mask = slots.wrapping_sub(1);
                for (i, &(key_hash, _)) in h.lexicon.iter().enumerate() {
                    let mut at = usize::try_from(key_hash).unwrap_or(0) & mask;
                    while h.lexicon_index.get(at).is_some_and(|&s| s != 0) {
                        at = at.wrapping_add(1) & mask;
                    }
                    if let Some(slot) = h.lexicon_index.get_mut(at) {
                        *slot = u32::try_from(i).ok()?.checked_add(1)?;
                    }
                }
            }
            parts.push(h);
        }
        Some(Model {
            strings,
            spelling,
            parts,
        })
    }

    pub fn spelling(&self) -> &Spelling<'a> {
        &self.spelling
    }

    /// Part of speech `index`, in the order the language's config declares them.
    pub fn pos(&self, index: usize) -> Option<Pos<'_, 'a>> {
        Some(Pos::new(self, self.parts.get(index)?))
    }

    pub fn pos_count(&self) -> usize {
        self.parts.len()
    }
}

